function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
	noStroke()
	fill(192, 32, 32, 128);
	fill(255);

	// noLoop() removed for animation
	frameRate(10)
}

function draw() {
	push()
	blendMode(DIFFERENCE);
	translate(width / 2, height / 2)
	rotate(-0.2 + frameCount - 1)
	rectMode(CENTER)
	rect(0, 0, width / 2, height / 2)
	rotate(0.4)
	rect(width / 2, 0, width, height * 2)
	pop()

	push()
	translate(width / 6, height / 6)
	rectMode(CENTER)

	const num = 3;
	for (let i = 0; i < num; i++) {
		rect(0, 0, width / 6, width / 18)
		rotate(-PI / num)
	}
	pop()
}

function mousePressed() {
	if (mouseButton === LEFT) {
		loop()
	}
}
